create function private.prepare_upload(p_conversation uuid,p_kind text,p_provider text) returns jsonb language plpgsql security definer set search_path='' as $$declare intent jsonb;begin if p_kind is null or p_kind not in('image','voice') or p_provider is null or p_provider not in('cloudinary','supabase') then raise exception 'Invalid upload';end if;if p_kind='voice' then intent:=private.prepare_voice(p_conversation);else intent:=private.prepare_image(p_conversation);end if;update private.images set provider=p_provider,format=case when p_provider='supabase' then case when p_kind='voice' then 'm4a' else 'jpg' end end where id=(intent->>'id')::uuid;return intent;end $$;create function public.prepare_upload(p_conversation uuid,p_kind text,p_provider text) returns jsonb language sql security invoker set search_path='' as $$select private.prepare_upload(p_conversation,p_kind,p_provider)$$;revoke all on function private.prepare_upload(uuid,text,text),public.prepare_upload(uuid,text,text) from public,anon,authenticated;grant execute on function private.prepare_upload(uuid,text,text),public.prepare_upload(uuid,text,text) to authenticated;
